#[cfg(test)]
mod tests {
    use super::*;
    use smallvec::SmallVec;
    use std::num::NonZeroU32;
    use sts2_core::card_effects::{apply_power_to_creature, install_default_registry};
    use sts2_core::cards::{Card, CardTags, CardType, TargetType};
    use sts2_core::{
        CombatPhase, Creature, CreatureUid, IntentHistory, MonsterId, MonsterKind, PowerKind,
    };

    /// Push a Strike-tagged Attack dealing ZERO damage into the draw pile.
    /// Strike-tagged → HellraiserPower auto-plays it on draw; zero damage → the
    /// recycle makes no progress, so it models the *go-nowhere* soft-lock the
    /// progress guard must catch (a damage-dealing recycle would self-terminate
    /// by killing the enemy and must NOT be stopped).
    fn push_zero_damage_strike(state: &mut CombatState) {
        let raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let uid = sts2_core::CardUid::new(raw).expect("non-zero");
        state.cards.push(Card {
            uid,
            card_id: CardId::StrikeIronclad,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 0,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::one(sts2_core::cards::CardTag::Strike),
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        state.player.draw.insert(0, uid);
    }

    /// Bead `sts2-rs-65mbx`: Pillage + an auto-play-on-draw power
    /// (HellraiserPower auto-plays drawn Strikes back to the discard) over an
    /// all-Attack draw pool that deals NO damage is a genuine STS2 soft-lock that
    /// goes nowhere — the do/while recycles forever (C# shares it;
    /// `CardPileCmd.Draw` reshuffles mid-action and the pool never empties), and
    /// nothing dies to end it. Pillage's progress guard must break it once a full
    /// draw-cycle passes with no enemy hp+block lost. **Without the guard this
    /// loop never returns.** (A damage-dealing recycle is a separate, *winning*
    /// case the guard deliberately leaves alone — it self-terminates on the
    /// kill.)
    #[test]
    fn pillage_zero_damage_recycle_soft_lock_is_bounded() {
        crate::cards::ironclad::install_pool();
        install_default_registry();
        let mut state = CombatState {
            rng: sts2_core::dotnet_rng::Rng::new(0_i32),
            ..Default::default()
        };
        state.player.current_hp = 80;
        state.player.max_hp = 80;
        state.player.energy = 3;
        state.phase = CombatPhase::PlayerPlayPhase;

        // Enemy that takes only Pillage's own hit (recycled Strikes deal 0), so
        // the recycle makes no progress and the combat never ends on its own.
        let enemy_id = NonZeroU32::new(1).expect("non-zero");
        state.creatures.push(Creature {
            id: enemy_id,
            current_hp: 100,
            max_hp: 100,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Nibbit"),
            ai: None,
        });
        let enemy_uid = CreatureUid(enemy_id);
        state.enemy_uids.push(enemy_uid);

        // Player mirror creature so the power applies via the mirror path.
        let player_id = NonZeroU32::new(100).expect("non-zero");
        state.creatures.push(Creature {
            id: player_id,
            current_hp: 80,
            max_hp: 80,
            block: 0,
            powers: SmallVec::new(),
            species: Some(MonsterKind::Nibbit),
            intent: None,
            intent_history: IntentHistory::default(),
            monster_id: MonsterId("Player"),
            ai: None,
        });
        state.player.creature_uid = Some(CreatureUid(player_id));
        apply_power_to_creature(&mut state, CreatureUid(player_id), PowerKind::Hellraiser, 1);

        // Put a Pillage on the Play pile — the dispatch contract has handlers
        // read the resolving card from `player.play`'s tail (`current_damage`).
        let pillage_raw = u32::try_from(state.cards.len() + 1).expect("fits");
        let pillage_uid = sts2_core::CardUid::new(pillage_raw).expect("non-zero");
        state.cards.push(Card {
            uid: pillage_uid,
            card_id: CardId::Pillage,
            cost: 1,
            card_type: CardType::Attack,
            target_type: TargetType::Enemy,
            upgraded: false,
            base_damage: 6,
            base_block: 0,
            combat_vars: sts2_core::cards::CombatVars::new(),
            enchantments: sts2_core::cards::CardEnchantments::new(),
            tags: CardTags::NONE,
            energy_spent: 0,
            base_replay_count: 0,
            keyword_override: None,
            affliction: None,
        });
        state.player.play.push(pillage_uid);

        // All-Attack, zero-damage draw pool: Hellraiser auto-plays each drawn
        // Strike out of hand (so it never fills) and they deal nothing (so the
        // recycle never progresses) — the soft-lock condition.
        for _ in 0..8 {
            push_zero_damage_strike(&mut state);
        }

        let hp_before = state.creatures[0].current_hp;
        // Without the progress guard, this call never returns.
        let res = play_pillage(&mut state, Some(enemy_uid));
        assert!(matches!(res, EffectResult::Resolved));

        // The loop actually entered the recycle and ran the no-progress window
        // before the guard broke it (not a trivial first-iteration break): many
        // cards were drawn.
        assert!(
            state.cards_drawn >= 10,
            "expected the recycle to draw many cards before the progress guard \
             broke it; got cards_drawn={}",
            state.cards_drawn
        );
        // Recycled Strikes dealt nothing — the enemy lost only Pillage's own 6,
        // confirming this was the go-nowhere case the guard is meant to stop.
        let dealt = hp_before - state.creatures[0].current_hp;
        assert_eq!(
            dealt, 6,
            "only Pillage's own hit should land (recycle deals 0); got {dealt}"
        );
    }
}
